/* Level-specific slides: S1, S2 and S3 each get their own explanations instead of sharing one set */
(function () { 'use strict';
var X = SK.X, S = FR.S;

/* ---------- S3: Number and percentages ---------- */
S.s3sf1 = X('Standard form with negative powers', 'Write 0.000 38 in standard form, and write 4.5 × 10⁷ as an ordinary number.', ['Move the decimal point to get a number between 1 and 10: 3.8.', 'It moved 4 places to the right, so the power is −4: 3.8 × 10⁻⁴.', 'For 4.5 × 10⁷ move the decimal point 7 places to the right: 45 000 000.', 'Small numbers have negative powers and large numbers have positive powers.'], ['0.000 38 → 3.8', '4 places → 10⁻⁴', '4.5 × 10⁷', '45 000 000'], '3.8 × 10⁻⁴ and 45 000 000', 'Scientists write the size of an atom and the distance to a star in this way.', 'how to write very large and very small numbers in standard form.', ['The first number must be at least 1 and less than 10.', 'Count the places the decimal point moves.'], ['Example 1: 6 200 000 = 6.2 × 10⁶.', 'Example 2: 0.007 = 7 × 10⁻³.', 'Example 3: 9.1 × 10⁻⁵ = 0.000 091.']);
S.s3sf2 = X('Multiplying and dividing in standard form', 'Work out (4 × 10⁵) × (3 × 10⁻²) and (6 × 10⁸) ÷ (2 × 10³).', ['Multiply the numbers: 4 × 3 = 12. Add the powers: 5 + (−2) = 3. That gives 12 × 10³.', '12 × 10³ is not in standard form. Write 12 as 1.2 × 10¹, so the answer is 1.2 × 10⁴.', 'Divide the numbers: 6 ÷ 2 = 3. Subtract the powers: 8 − 3 = 5.', 'So (6 × 10⁸) ÷ (2 × 10³) = 3 × 10⁵.'], ['4 × 3 = 12, 5 + (−2) = 3', '12 × 10³ = 1.2 × 10⁴', '6 ÷ 2 = 3, 8 − 3 = 5', '3 × 10⁵'], '1.2 × 10⁴ and 3 × 10⁵', 'Astronomers multiply and divide huge numbers like this.', 'how to multiply and divide numbers in standard form.', ['Deal with the numbers and the powers separately.', 'Check your answer is back in standard form.'], ['Example 1: (2 × 10³) × (5 × 10⁴) = 10 × 10⁷ = 1 × 10⁸.', 'Example 2: (9 × 10⁶) ÷ (3 × 10²) = 3 × 10⁴.', 'Example 3: (5 × 10⁻³) × (2 × 10⁻²) = 1 × 10⁻⁴.']);
S.s3bounds = X('Rounding and upper and lower bounds', 'A rectangle is 8 cm by 5 cm, each measured to the nearest cm. Find the greatest and least possible area.', ['A length given to the nearest cm lies from 0.5 below to 0.5 above.', 'The length is between 7.5 and 8.5 and the width is between 4.5 and 5.5.', 'Greatest area = 8.5 × 5.5 = 46.75 cm².', 'Least area = 7.5 × 4.5 = 33.75 cm².'], ['7.5 ≤ l < 8.5', '4.5 ≤ w < 5.5', '8.5 × 5.5 = 46.75', '7.5 × 4.5 = 33.75'], 'between 33.75 cm² and 46.75 cm²', 'Engineers must know the largest and smallest sizes a part could really be.', 'how to find the limits of a rounded measurement and use them in a calculation.', ['Half of the rounding unit goes each way.', 'For the greatest answer use all the upper bounds in a product.'], ['Example 1: 6 cm to the nearest cm is from 5.5 to 6.5.', 'Example 2: 250 g to the nearest 10 g is from 245 to 255.', 'Example 3: the least perimeter uses the lower bounds.']);
S.s3irr = X('Rational and irrational numbers', 'Which of these are rational: 0.25, √2, 2/3, √49, π?', ['A rational number can be written as a fraction of two whole numbers.', '0.25 = 1/4, 2/3 and √49 = 7 = 7/1 are all rational.', '√2 and π cannot be written as a fraction. Their decimals never end and never repeat.', 'So 0.25, 2/3 and √49 are rational, while √2 and π are irrational.'], ['0.25 = 1/4', '√49 = 7', '√2, π never repeat', 'rational or irrational'], '0.25, 2/3 and √49 are rational; √2 and π are irrational', 'The diagonal of a unit square is √2, a length that cannot be written exactly as a fraction.', 'how to tell rational and irrational numbers apart.', ['A square root of a non-square whole number is irrational.', 'Terminating and recurring decimals are rational.'], ['Example 1: √3 is irrational.', 'Example 2: 0.333… = 1/3 is rational.', 'Example 3: √100 = 10 is rational.']);
S.s3pcc = X('Percentage change in context', 'A phone costs £250 in May and £310 in June. Find the percentage change.', ['Find the change: 310 − 250 = £60.', 'Percentage change = change ÷ original × 100.', '60 ÷ 250 = 0.24, and 0.24 × 100 = 24%.', 'The price increased by 24%.'], ['310 − 250 = 60', 'change ÷ original', '60 ÷ 250 = 0.24', '24% increase'], '24% increase', 'Shops, wages and population all report percentage change.', 'how to find a percentage increase or decrease from two values.', ['Always divide by the original amount.', 'A decrease is a negative change.'], ['Example 1: £80 to £60 is a 25% decrease.', 'Example 2: 40 to 50 is a 25% increase, but 50 to 40 is a 20% decrease.', 'Example 3: a population of 12 000 rising to 13 200 is a 10% increase.']);
S.s3repeat = X('Repeated percentage change', 'A price is cut by 20% and then raised by 20%. Is it back to the start?', ['Start at 100%. After a 20% cut, multiply by 0.8: 100 × 0.8 = 80.', 'Raise by 20%: multiply by 1.2: 80 × 1.2 = 96.', 'The final price is 96% of the original, so it is 4% lower.', 'Multipliers can be combined: 0.8 × 1.2 = 0.96.'], ['100 × 0.8 = 80', '80 × 1.2 = 96', '96% of the start', '0.8 × 1.2 = 0.96'], 'No, it is 4% lower', 'Sales, wages and savings change by percentages one after another.', 'how to combine percentage changes with multipliers.', ['An increase of r% has multiplier 1 + r/100.', 'A decrease of r% has multiplier 1 − r/100.'], ['Example 1: +10% then +10% has multiplier 1.1 × 1.1 = 1.21, a 21% increase.', 'Example 2: −50% then +50% has multiplier 0.75.', 'Example 3: three 10% rises multiply by 1.331.']);

/* ---------- S3: Finance ---------- */
S.s3tax = X('Tax bands and take-home pay', 'In an example tax system the first £12 000 is tax-free and the rest is taxed at 20%. Find the tax and the take-home pay on a salary of £34 000.', ['Taxable pay = 34 000 − 12 000 = £22 000.', 'Tax = 20% of 22 000 = 0.2 × 22 000 = £4 400.', 'Take-home pay = 34 000 − 4 400 = £29 600.', 'Divide by 12 for monthly take-home pay: £2 466.67.'], ['34 000 − 12 000', '0.2 × 22 000 = 4 400', '34 000 − 4 400', '£29 600'], 'Tax £4 400 and take-home pay £29 600', 'Pay slips show gross pay, tax and take-home pay.', 'how tax-free allowances and tax rates are used.', ['Tax is only on the amount above the allowance.', 'Real tax rates and bands change, so always check the current ones.'], ['Example 1: the tax on £20 000 with a £12 000 allowance at 20% is £1 600.', 'Example 2: monthly gross pay is the annual pay ÷ 12.', 'Example 3: a bigger allowance means less tax.']);
S.s3vat = X('Prices with VAT', 'A tablet costs £150 including 20% VAT. Find the price before VAT and the VAT paid.', ['Including VAT, the price is 120% of the original: 1.2 × original = 150.', 'Original price = 150 ÷ 1.2 = £125.', 'VAT = 150 − 125 = £25.', 'Check: 20% of 125 = £25 ✓.'], ['1.2 × original = 150', '150 ÷ 1.2 = 125', '150 − 125 = 25', '20% of 125 = 25'], '£125 before VAT and £25 VAT', 'Shop prices include VAT, but businesses work with the price before VAT.', 'how to remove VAT from a price that already includes it.', ['Divide by 1.2 to take off 20% VAT.', 'Do not take 20% of the final price. That gives the wrong answer.'], ['Example 1: £60 plus 20% VAT is £72.', 'Example 2: £72 including VAT is £60 before VAT.', 'Example 3: VAT of £12 means the price before VAT was £60.']);
S.s3credit = X('The cost of credit', 'A sofa costs £1 200. You can pay £60 a month for 24 months. How much extra do you pay, as a percentage of the cash price?', ['Total paid = 60 × 24 = £1 440.', 'Extra cost = 1 440 − 1 200 = £240.', 'Percentage extra = 240 ÷ 1 200 × 100 = 20%.', 'Paying monthly costs 20% more than paying cash.'], ['60 × 24 = 1 440', '1 440 − 1 200 = 240', '240 ÷ 1 200 = 0.2', '20%'], '£240 extra, which is 20%', 'Credit makes things easier to afford but costs more in total.', 'how to work out the total cost of buying on credit.', ['Always compare the total paid with the cash price.', 'A lower monthly payment may mean a longer time and more interest.'], ['Example 1: a deposit of £100 plus 12 payments of £50 costs £700.', 'Example 2: borrowing £500 and repaying £560 is 12% extra.', 'Example 3: always check the total, not just the monthly cost.']);
S.s3fx = X('Comparing currency offers', 'You exchange £500. Shop A gives €1.15 per £1 with 2% commission. Shop B gives €1.12 per £1 and no commission. Which is better?', ['Shop A: 500 × 1.15 = €575.', 'Commission: 2% of 575 = €11.50, so you get 575 − 11.50 = €563.50.', 'Shop B: 500 × 1.12 = €560.', '€563.50 is more than €560, so Shop A is better.'], ['500 × 1.15 = 575', '575 − 11.50 = 563.50', '500 × 1.12 = 560', 'A is better'], 'Shop A: €563.50 compared with €560', 'Travellers compare exchange offers to get the most for their money.', 'how to compare exchange rates that include commission.', ['Work out what you receive for each offer, including all fees.', 'The best rate is not always the best offer.'], ['Example 1: £200 at €1.2 is €240.', 'Example 2: €300 at €1.2 per £1 costs £250.', 'Example 3: 1% commission on €240 is €2.40.']);

/* ---------- S3: Ratio, proportion, rates and speed ---------- */
S.s3ratio = X('Ratios that change', 'The ratio of boys to girls in a club is 3 : 4. After 6 more boys join, the numbers are equal. How many girls are there?', ['Let the boys be 3x and the girls 4x.', 'After 6 boys join the boys are 3x + 6, and this equals the girls: 3x + 6 = 4x.', 'Solve: x = 6.', 'Girls = 4 × 6 = 24 (and boys became 18 + 6 = 24).'], ['boys 3x, girls 4x', '3x + 6 = 4x', 'x = 6', '4 × 6 = 24'], '24 girls', 'Group sizes, mixtures and sharing often change while a ratio stays the same.', 'how to set up an equation when a ratio changes.', ['Use x for one part.', 'Check the final numbers against the new condition.'], ['Example 1: 2 : 3 with 10 more of the first becomes equal, so x = 10.', 'Example 2: boys 18, girls 24 is 3 : 4.', 'Example 3: after the change the totals are the same.']);
S.s3dir = X('Direct proportion and formulae', 'y is directly proportional to x. When x = 4, y = 10. Find the formula and the value of y when x = 14.', ['Direct proportion means y = kx.', 'Use the known pair: 10 = k × 4, so k = 2.5.', 'The formula is y = 2.5x.', 'When x = 14: y = 2.5 × 14 = 35.'], ['y = kx', '10 = 4k, k = 2.5', 'y = 2.5x', '2.5 × 14 = 35'], 'y = 2.5x, so y = 35', 'Cost per kilogram and pay per hour are direct proportions.', 'how to write a formula for direct proportion and use it.', ['The graph is a straight line through the origin.', 'Doubling x doubles y.'], ['Example 1: y = 3x, so x = 5 gives y = 15.', 'Example 2: if x = 8 gives y = 20 then k = 2.5.', 'Example 3: y = kx has gradient k.']);
S.s3inv = X('Inverse proportion and formulae', 'The time t to fill a tank is inversely proportional to the number of pumps n. 3 pumps take 8 hours. How long do 5 pumps take?', ['Inverse proportion means t × n stays the same, so t = k ÷ n.', 'k = 8 × 3 = 24, so t = 24 ÷ n.', 'For 5 pumps: t = 24 ÷ 5 = 4.8 hours.', '4.8 hours = 4 hours 48 minutes.'], ['t = k ÷ n', 'k = 8 × 3 = 24', '24 ÷ 5 = 4.8', '4 h 48 min'], '4.8 hours (4 hours 48 minutes)', 'More workers or machines take less time for the same job.', 'how to write a formula for inverse proportion and use it.', ['If one goes up, the other goes down.', 'The product of the two stays the same.'], ['Example 1: 6 workers take 4 days, so 8 workers take 3 days.', 'Example 2: y = 12 ÷ x, so x = 4 gives y = 3.', 'Example 3: doubling the speed halves the time.']);
S.s3avg = X('Average speed over a whole journey', 'A cyclist rides 30 km at 15 km/h and then 30 km at 10 km/h. Find the average speed for the whole journey.', ['Time for the first part = 30 ÷ 15 = 2 hours.', 'Time for the second part = 30 ÷ 10 = 3 hours.', 'Total distance 60 km in 5 hours.', 'Average speed = 60 ÷ 5 = 12 km/h, not 12.5 km/h.'], ['30 ÷ 15 = 2 h', '30 ÷ 10 = 3 h', '60 km in 5 h', '12 km/h'], '12 km/h', 'Journey planners use total distance and total time.', 'how to find an average speed for a journey in several parts.', ['Average speed = total distance ÷ total time.', 'Do not just average the speeds.'], ['Example 1: 100 km in 2 hours is 50 km/h.', 'Example 2: 40 km at 20 km/h then 40 km at 40 km/h is 80 km in 3 hours, about 26.7 km/h.', 'Example 3: stops count towards the total time.']);
S.s3unit = X('Value for money with unit rates', 'A 750 ml bottle costs £2.10 and a 2 l bottle costs £5.40. Which is better value?', ['Change 2 l to 2 000 ml.', '750 ml: 210p ÷ 750 = 0.28p per ml.', '2 000 ml: 540p ÷ 2 000 = 0.27p per ml.', '0.27p per ml is cheaper, so the 2 l bottle is better value.'], ['2 l = 2 000 ml', '210 ÷ 750 = 0.28', '540 ÷ 2 000 = 0.27', 'the 2 l bottle'], 'The 2 l bottle', 'Shoppers compare sizes and prices every day.', 'how to compare prices using unit rates.', ['Use the same units for both.', 'Compare the cost per unit, or the amount per penny.'], ['Example 1: 500 g for £1.20 is 0.24p per gram.', 'Example 2: 3 for £2 is about 67p each.', 'Example 3: the cheapest per unit is not always the right size.']);

/* ---------- S3: Area, solids, algebra, equations, lines ---------- */
S.s3comp = X('Compound shapes with a semicircle', 'A window is a rectangle 80 cm by 120 cm with a semicircle of diameter 80 cm on top. Find its area.', ['Rectangle: 80 × 120 = 9 600 cm².', 'The semicircle has radius 40 cm: ½ × π × 40² = ½ × π × 1 600 = 800π.', '800π ≈ 2 513 cm².', 'Total area = 9 600 + 2 513 ≈ 12 113 cm².'], ['80 × 120 = 9 600', '½ × π × 40²', '800π ≈ 2 513', '≈ 12 113'], 'about 12 113 cm²', 'Windows, doors and arches combine rectangles and circles.', 'how to find the area of a shape made from a rectangle and a semicircle.', ['Split the shape into simple parts.', 'Halve the circle area for a semicircle.'], ['Example 1: a semicircle of radius 3 has area 4.5π.', 'Example 2: add the parts together.', 'Example 3: subtract a hole from a larger shape.']);
S.s3volrev = X('Working backwards from a volume', 'A cylinder has volume 500 cm³ and radius 5 cm. Find its height.', ['Volume = πr²h.', '500 = π × 25 × h, so h = 500 ÷ (25π).', '25π ≈ 78.54, so h = 500 ÷ 78.54 ≈ 6.37 cm.', 'Check: π × 25 × 6.37 ≈ 500 ✓.'], ['V = πr²h', '500 = 25πh', '500 ÷ 78.54', '≈ 6.37 cm'], 'about 6.4 cm', 'Tank and tin designers work out the height they need for a given volume.', 'how to find a missing length from a volume.', ['Write the formula first, then rearrange.', 'Check the answer by substituting back.'], ['Example 1: a cuboid of volume 60 cm³ with base 5 by 4 has height 3 cm.', 'Example 2: a cylinder of volume 150π with r = 5 has h = 6.', 'Example 3: a cone has volume ⅓πr²h.']);
S.s3brk = X('Expanding with negatives and simplifying', 'Expand and simplify 3(2x − 4) − 2(x − 5).', ['Expand the first bracket: 3(2x − 4) = 6x − 12.', 'Expand the second: −2(x − 5) = −2x + 10. The minus sign changes both signs.', 'Collect like terms: 6x − 2x = 4x and −12 + 10 = −2.', 'The answer is 4x − 2.'], ['6x − 12', '−2x + 10', '4x and −2', '4x − 2'], '4x − 2', 'Simplifying expressions is the first step in solving many problems.', 'how to expand two brackets with a minus sign and simplify.', ['A minus in front of a bracket changes every sign inside.', 'Collect like terms at the end.'], ['Example 1: 2(x + 3) + 3(x − 1) = 5x + 3.', 'Example 2: 4(a − 2) − (a + 1) = 3a − 9.', 'Example 3: −3(x − 2) = −3x + 6.']);
S.s3fac = X('Factorising fully', 'Factorise fully 12x²y − 18xy².', ['Find the HCF of 12 and 18: 6.', 'The common letters are x and y, each to the smallest power: xy.', 'The common factor is 6xy: 12x²y ÷ 6xy = 2x and 18xy² ÷ 6xy = 3y.', 'So 12x²y − 18xy² = 6xy(2x − 3y).'], ['HCF of 12 and 18 = 6', 'common letters xy', '12x²y ÷ 6xy = 2x', '6xy(2x − 3y)'], '6xy(2x − 3y)', 'Factorising makes expressions easier to simplify and solve.', 'how to take out the highest common factor of numbers and letters.', ['Factorise fully means no more common factors are left.', 'Check by expanding the answer.'], ['Example 1: 8x + 12 = 4(2x + 3).', 'Example 2: 6a²b + 9ab = 3ab(2a + 3).', 'Example 3: x² − 5x = x(x − 5).']);
S.s3ineq = X('Inequalities with brackets', 'Solve 3(x − 2) ≥ 2x + 5.', ['Expand the bracket: 3x − 6 ≥ 2x + 5.', 'Subtract 2x from both sides: x − 6 ≥ 5.', 'Add 6 to both sides: x ≥ 11.', 'Check with x = 12: 3 × 10 = 30 ≥ 29 ✓.'], ['3x − 6 ≥ 2x + 5', 'x − 6 ≥ 5', 'x ≥ 11', 'test x = 12'], 'x ≥ 11', 'Limits and conditions in real problems are written as inequalities.', 'how to solve an inequality that has a bracket.', ['Solve like an equation, but reverse the sign when multiplying or dividing by a negative.', 'Check with a test value.'], ['Example 1: 2x + 3 < 11 gives x < 4.', 'Example 2: −2x > 6 gives x < −3.', 'Example 3: x ≥ 11 includes 11.']);
S.s3grad = X('Gradient from two points', 'The cost of a taxi ride is £3 for 2 miles and £15 for 8 miles. Find the gradient of the line through (2, 3) and (8, 15) and say what it means.', ['Gradient = change in y ÷ change in x.', 'Change in y = 15 − 3 = 12. Change in x = 8 − 2 = 6.', '12 ÷ 6 = 2.', 'The cost goes up £2 for every extra mile.'], ['change in y = 12', 'change in x = 6', '12 ÷ 6 = 2', '£2 per mile'], 'gradient 2 (£2 per mile)', 'The gradient of a real graph is a rate such as speed, cost per unit or temperature change per hour.', 'how to find a gradient from two points and say what it means.', ['Subtract the y values and the x values in the same order.', 'Use units in your answer.'], ['Example 1: (1, 2) and (4, 11) has gradient 3.', 'Example 2: a horizontal line has gradient 0.', 'Example 3: a line going down has a negative gradient.']);
S.s3mc = X('Reading y = mx + c from a real graph', 'A plumber charges a call-out fee plus an hourly rate: C = 25 + 40h. State the gradient and the y-intercept and the cost of a 3-hour job.', ['Rewrite as C = 40h + 25 and compare with y = mx + c.', 'The gradient is m = 40: the cost per hour. The y-intercept is c = 25: the call-out fee.', 'For h = 3: C = 40 × 3 + 25 = 120 + 25.', 'C = £145.'], ['C = 40h + 25', 'm = 40, c = 25', '40 × 3 + 25', '£145'], 'gradient 40, y-intercept 25, cost £145', 'Many prices combine a fixed fee with a charge per unit.', 'how to read the gradient and y-intercept from a formula and explain them.', ['The gradient is the change per unit.', 'The y-intercept is the starting value.'], ['Example 1: y = 3x + 2 has gradient 3 and cuts the y-axis at 2.', 'Example 2: C = 50 + 20h has a £50 fixed charge.', 'Example 3: a phone plan of £10 plus 5p per minute is C = 10 + 0.05m.']);
S.s3point = X('Equation of a line from a point and a gradient', 'Find the equation of the line with gradient 3 that passes through (2, 5).', ['Start with y = mx + c and put in m = 3: y = 3x + c.', 'Substitute the point (2, 5): 5 = 3 × 2 + c, so 5 = 6 + c.', 'Solve: c = −1.', 'The equation is y = 3x − 1.'], ['y = 3x + c', '5 = 6 + c', 'c = −1', 'y = 3x − 1'], 'y = 3x − 1', 'Predictions from a trend line use an equation like this.', 'how to find the equation of a line when you know a point and the gradient.', ['Substitute the point into y = mx + c to find c.', 'Check by putting the point back into the equation.'], ['Example 1: gradient 2 through (1, 7) gives y = 2x + 5.', 'Example 2: gradient −1 through (3, 4) gives y = −x + 7.', 'Example 3: gradient ½ through (4, 3) gives y = ½x + 1.']);

/* ---------- S3: Pythagoras, circle, similarity, statistics ---------- */
S.s3pyth = X('Pythagoras in context', 'A 5 m ladder rests against a wall with its foot 1.4 m from the wall. How high up the wall does it reach?', ['The ladder is the hypotenuse, 5 m.', 'Let the height be h: h² + 1.4² = 5².', 'h² = 25 − 1.96 = 23.04.', 'h = √23.04 = 4.8 m.'], ['h² + 1.4² = 5²', 'h² = 25 − 1.96', 'h² = 23.04', 'h = 4.8 m'], '4.8 m', 'Builders use Pythagoras to check heights and square corners.', 'how to use Pythagoras in a real problem with a diagram.', ['Draw the right-angled triangle and label the hypotenuse.', 'When finding a short side, subtract the squares.'], ['Example 1: a ramp of length 13 m rises 5 m, so the horizontal distance is 12 m.', 'Example 2: a TV with a diagonal of 50 cm and width 40 cm has height 30 cm.', 'Example 3: always check the answer is shorter than the hypotenuse.']);
S.s3dist = X('The distance between two points', 'Find the distance between A(1, 2) and B(7, 10).', ['Draw a right-angled triangle: across 7 − 1 = 6, up 10 − 2 = 8.', 'AB² = 6² + 8² = 36 + 64 = 100.', 'AB = √100 = 10.', 'The distance AB is 10 units.'], ['across 6, up 8', '6² + 8² = 100', '√100', '10'], '10 units', 'Maps and computer games use coordinates to find distances.', 'how to find the distance between two points on a grid.', ['Find the difference in x and the difference in y.', 'The distance is the hypotenuse.'], ['Example 1: (0, 0) to (3, 4) is 5.', 'Example 2: (2, 1) to (5, 5) is 5.', 'Example 3: (1, 1) to (4, 5) is 5.']);
S.s3surd = X('Exact answers with surds', 'A right-angled triangle has short sides 3 cm and 5 cm. Find the hypotenuse exactly.', ['h² = 3² + 5² = 9 + 25 = 34.', 'h = √34.', '34 has no square factors, so √34 cannot be simplified.', 'As a decimal, √34 ≈ 5.83 cm.'], ['9 + 25 = 34', 'h = √34', 'no square factors', '≈ 5.83'], '√34 cm ≈ 5.83 cm', 'Exact answers avoid rounding errors in a longer calculation.', 'how to leave an answer as a surd.', ['Leave the root unless the question asks for a decimal.', 'Simplify if there is a square factor, for example √50 = 5√2.'], ['Example 1: √12 = 2√3.', 'Example 2: √18 = 3√2.', 'Example 3: 2² + 2² = 8 so the hypotenuse is 2√2.']);
S.s3conv = X('Checking for a right angle', 'Show that a triangle with sides 20, 21 and 29 is right-angled.', ['The longest side is 29, so it would be the hypotenuse.', 'Check 20² + 21² = 400 + 441 = 841.', '29² = 841.', 'They are equal, so the triangle is right-angled.'], ['longest side 29', '400 + 441 = 841', '29² = 841', 'right-angled'], 'Yes: 20² + 21² = 29²', 'A builder checks a corner is square using a 3-4-5 triangle.', 'how to prove a triangle has a right angle.', ['Always test the longest side as the hypotenuse.', 'If the sum is not equal, the triangle is not right-angled.'], ['Example 1: 5, 12, 13 is right-angled.', 'Example 2: 6, 7, 10 is not right-angled.', 'Example 3: 8, 15, 17 is right-angled.']);
S.s3circ = X('Circles in terms of π', 'A circle has diameter 12 cm. Find the circumference and area in terms of π.', ['The radius is 12 ÷ 2 = 6 cm.', 'Circumference = πd = 12π cm.', 'Area = πr² = π × 36 = 36π cm².', 'As decimals these are about 37.7 cm and 113.1 cm².'], ['r = 6', 'C = πd = 12π', 'A = πr² = 36π', '37.7 and 113.1'], '12π cm and 36π cm²', 'Leaving π in the answer keeps it exact.', 'how to give circle answers exactly in terms of π.', ['Round only at the very end.', 'Check whether you were given the radius or the diameter.'], ['Example 1: r = 5 gives C = 10π.', 'Example 2: d = 10 gives A = 25π.', 'Example 3: A = 49π means r = 7.']);
S.s3rev = X('Working backwards from circumference or area', 'A circle has circumference 31.4 cm. Find its radius and then its area.', ['C = 2πr, so r = C ÷ 2π = 31.4 ÷ 6.283 = 5 cm.', 'Area = πr² = π × 25.', 'Area ≈ 78.5 cm².', 'Check: C = 2 × 3.14 × 5 = 31.4 ✓.'], ['r = 31.4 ÷ 2π', 'r = 5', 'A = π × 25', '78.5'], 'radius 5 cm, area about 78.5 cm²', 'Designers often know the size of a circle and need its radius.', 'how to find the radius from the circumference or the area.', ['Rearrange the formula before using numbers.', 'For the area, r = √(A ÷ π).'], ['Example 1: C = 20π gives r = 10.', 'Example 2: A = 100π gives r = 10.', 'Example 3: d = C ÷ π.']);
S.s3track = X('Perimeters with semicircles', 'A running track has two straights of 100 m and two semicircular ends with diameter 40 m. How long is one lap?', ['The two semicircular ends together make one full circle of diameter 40 m.', 'Circumference = π × 40 ≈ 125.7 m.', 'The two straights add 100 + 100 = 200 m.', 'One lap ≈ 200 + 125.7 = 325.7 m.'], ['one circle, d = 40', 'π × 40 ≈ 125.7', '2 × 100 = 200', '≈ 325.7 m'], 'about 325.7 m', 'Athletics tracks are designed with straights and semicircles.', 'how to find the perimeter of a shape with curved ends.', ['Join the two curved parts mentally to make a circle.', 'Add straight and curved lengths.'], ['Example 1: a semicircle of diameter 10 has curved length 5π.', 'Example 2: add the diameter to get the perimeter of a semicircle.', 'Example 3: a standard 400 m track has straights of about 85 m.']);
S.s3sector = X('Arc length and sector area', 'A sector has radius 10 cm and angle 72°. Find its arc length and its area.', ['The sector is 72 ÷ 360 = 1/5 of the whole circle.', 'Arc length = 1/5 × 2π × 10 = 4π ≈ 12.6 cm.', 'Sector area = 1/5 × π × 10² = 20π ≈ 62.8 cm².', 'The fraction 72/360 is used for both.'], ['72 ÷ 360 = 1/5', 'arc = 4π ≈ 12.6', 'area = 20π ≈ 62.8', 'same fraction'], 'arc 4π ≈ 12.6 cm, area 20π ≈ 62.8 cm²', 'Pizza slices, clock hands and wipers sweep sectors.', 'how to find an arc length and a sector area using a fraction of the circle.', ['Angle ÷ 360 gives the fraction of the circle.', 'Arc length uses the circumference; sector area uses the area.'], ['Example 1: a quarter circle of radius 4 has area 4π.', 'Example 2: 90° of radius 6 has arc 3π.', 'Example 3: 180° of radius 5 has area 12.5π.']);
S.s3sim = X('Missing sides in similar shapes', 'Triangles ABC and DEF are similar. AB = 6 cm, BC = 9 cm and DE = 10 cm. Find EF.', ['AB matches DE, so the scale factor is 10 ÷ 6 = 5/3.', 'EF matches BC, so EF = 9 × 5/3.', '9 × 5 ÷ 3 = 15.', 'EF = 15 cm.'], ['10 ÷ 6 = 5/3', 'EF = 9 × 5/3', '45 ÷ 3', '15 cm'], 'EF = 15 cm', 'Model makers use scale factors to keep proportions right.', 'how to find a missing side in similar shapes.', ['Match the corresponding sides first.', 'Use the same scale factor for every side.'], ['Example 1: scale factor 2 turns 4 cm into 8 cm.', 'Example 2: a smaller image has scale factor less than 1.', 'Example 3: check with a second pair of sides.']);
S.s3map = X('Scale drawings and map scales', 'On a map with scale 1 : 25 000, two villages are 8.4 cm apart. How far apart are they in km?', ['Real distance = 8.4 × 25 000 = 210 000 cm.', 'Change cm to m: 210 000 ÷ 100 = 2 100 m.', 'Change m to km: 2 100 ÷ 1 000 = 2.1 km.', 'The villages are 2.1 km apart.'], ['8.4 × 25 000', '210 000 cm', '2 100 m', '2.1 km'], '2.1 km', 'Walkers use map scales to plan routes.', 'how to change a map distance into a real distance.', ['Multiply by the scale, then change units.', 'For 1 : 50 000, 1 cm is 500 m.'], ['Example 1: 1 : 1 000 000 means 1 cm is 10 km.', 'Example 2: 4 cm at 1 : 50 000 is 2 km.', 'Example 3: to go from real to map divide by the scale.']);
S.s3simtri = X('Similar triangles in real problems', 'A 1.5 m post casts a 2 m shadow. A tree casts a 12 m shadow at the same time. How tall is the tree?', ['The triangles are similar, with scale factor 12 ÷ 2 = 6.', 'Height of the tree = 1.5 × 6.', '1.5 × 6 = 9.', 'The tree is 9 m tall.'], ['scale factor 6', '1.5 × 6', '9', '9 m'], '9 m', 'Surveyors find heights they cannot measure directly.', 'how to use similar triangles to find a height.', ['Draw two triangles and match the sides.', 'Write the scale factor first.'], ['Example 1: a 2 m pole with a 3 m shadow beside a 9 m shadow means a 6 m tree.', 'Example 2: sun angles must match for the triangles to be similar.', 'Example 3: check the answer is bigger than the post.']);
S.s3area = X('Area and volume scale factors together', 'Two similar cans have heights 10 cm and 15 cm. The small can holds 400 ml. How much does the large can hold, and what is the ratio of their surface areas?', ['Length scale factor = 15 ÷ 10 = 1.5.', 'Volume scale factor = 1.5³ = 3.375, so capacity = 400 × 3.375 = 1 350 ml.', 'Area scale factor = 1.5² = 2.25.', 'Ratio of surface areas = 1 : 2.25, which is 4 : 9.'], ['k = 1.5', '1.5³ = 3.375', '1.5² = 2.25', '4 : 9'], '1 350 ml, and the surface areas are in the ratio 4 : 9', 'Packaging firms scale cans and boxes up and down.', 'how to use length, area and volume scale factors together.', ['Area scales by k² and volume by k³.', 'Write the scale factor before choosing the power.'], ['Example 1: k = 2 gives area × 4 and volume × 8.', 'Example 2: k = 3 gives area × 9.', 'Example 3: a ratio of areas of 4 : 9 gives lengths in the ratio 2 : 3.']);
S.s3bear = X('Bearings and trigonometry', 'A ship sails 12 km on a bearing of 090° and then 5 km on a bearing of 180°. Find the distance from the start and the bearing of the finish from the start.', ['The legs are at right angles, so 12² + 5² = 169 and the distance is √169 = 13 km.', 'The angle below East is tan⁻¹(5 ÷ 12) ≈ 22.6°.', 'Bearing = 90° + 22.6° = 112.6°.', 'The ship finishes 13 km away on a bearing of about 113°.'], ['12² + 5² = 169', '√169 = 13', 'tan⁻¹(5/12) ≈ 22.6°', '≈ 113°'], '13 km on a bearing of about 113°', 'Navigators combine distances and bearings to plot a position.', 'how to use trigonometry and Pythagoras to work out a bearing.', ['Sketch the journey and mark North at each turning point.', 'Check the bearing is in the right quarter of the compass.'], ['Example 1: 3 km North and 4 km East is 5 km on a bearing of 053°.', 'Example 2: the return bearing adds or subtracts 180°.', 'Example 3: bearings are always measured clockwise from North.']);
S.s3lobf = X('Predicting from a line of best fit', 'A line of best fit passes through (10, 20) and (40, 50). Estimate y when x = 25, and explain why x = 100 would be unreliable.', ['The gradient is (50 − 20) ÷ (40 − 10) = 1.', 'Using y = x + c with (10, 20): c = 10, so y = x + 10.', 'At x = 25, y = 35.', 'x = 100 is far outside the data, so this extrapolation is unreliable.'], ['gradient 1', 'y = x + 10', 'x = 25 gives 35', 'extrapolation is unreliable'], 'y = 35; extrapolating to x = 100 is unreliable', 'Scientists use trend lines to predict, but only within the range of their data.', 'how to use a line of best fit and say when it is reliable.', ['Interpolation is inside the data range and is more reliable.', 'Extrapolation goes outside the range and may be wrong.'], ['Example 1: 12 cm of rain predicted from 8 hours is interpolation.', 'Example 2: correlation does not prove one thing causes another.', 'Example 3: a line of best fit need not go through any point.']);
S.s3prob = X('Probability with overlapping events', 'In a class of 30, 18 play football, 12 play hockey and 5 play both. What is the probability that a pupil plays at least one?', ['Add and then remove the overlap: 18 + 12 − 5 = 25.', '25 pupils play at least one sport.', 'P(at least one) = 25/30.', 'Simplify: 5/6.'], ['18 + 12 − 5', '25 pupils', '25/30', '5/6'], '5/6', 'Surveys often have people in more than one group.', 'how to find the probability when two events overlap.', ['Subtract the overlap so it is not counted twice.', 'A Venn diagram makes the numbers clear.'], ['Example 1: P(A or B) = P(A) + P(B) − P(A and B).', 'Example 2: 30 − 25 = 5 pupils play neither.', 'Example 3: the probability of neither is 1/6.']);

/* ---------- S2: replacements for slides that S1 also uses ---------- */
S.s2pct = X('Percentages of amounts without a calculator', 'Find 35% of £240 without a calculator, then 17.5% of £80.', ['10% of £240 = £24, and 5% = £12. So 35% = 3 × 24 + 12 = 72 + 12 = £84.', 'For 17.5% of £80: 10% = £8, 5% = £4 and 2.5% = £2.', '17.5% = 8 + 4 + 2 = £14.', 'Check: 0.175 × 80 = 14 ✓.'], ['35% = 3 × 10% + 5%', '72 + 12 = 84', '10% + 5% + 2.5%', '£14'], '£84 and £14', 'Shop discounts and tips are often found in your head.', 'how to build up a percentage from 10%, 5% and 1%.', ['Find 10% first by dividing by 10.', 'Halve it to get 5%, halve again to get 2.5%.'], ['Example 1: 15% of 60 = 6 + 3 = 9.', 'Example 2: 1% of 400 = 4.', 'Example 3: 12.5% is one eighth.']);
S.s2compare = X('Comparing results using percentages', 'In Test 1 you score 36 out of 45. In Test 2 you score 52 out of 80. Which is the better result?', ['Change each score to a percentage.', '36 ÷ 45 = 0.8 = 80%.', '52 ÷ 80 = 0.65 = 65%.', '80% is higher than 65%, so Test 1 is better.'], ['36 ÷ 45 = 0.8', '52 ÷ 80 = 0.65', '80% and 65%', 'Test 1'], 'Test 1 (80% compared with 65%)', 'Percentages let you compare scores out of different totals.', 'how to compare amounts out of different totals using percentages.', ['Divide the part by the whole and multiply by 100.', 'Always compare like with like.'], ['Example 1: 18 out of 24 is 75%.', 'Example 2: 7 out of 8 is 87.5%.', 'Example 3: 45 out of 60 is 75%.']);
S.s2time = X('Time calculations across midnight', 'A flight leaves at 22:40 and lands at 07:15 the next day. How long is the flight?', ['From 22:40 to midnight is 1 h 20 min.', 'From midnight to 07:15 is 7 h 15 min.', 'Add: 1 h 20 min + 7 h 15 min = 8 h 35 min.', 'The flight takes 8 hours 35 minutes.'], ['22:40 to 24:00 = 1 h 20', '00:00 to 07:15 = 7 h 15', '1 h 20 + 7 h 15', '8 h 35 min'], '8 h 35 min', 'Overnight trains and flights cross midnight.', 'how to find a time difference that crosses midnight.', ['Split the journey at midnight.', 'Add the two parts.'], ['Example 1: 23:30 to 01:10 is 1 h 40 min.', 'Example 2: 18:45 to 02:15 is 7 h 30 min.', 'Example 3: use 24-hour time to avoid errors.']);
S.s2speed = X('Speed, distance and time with unit changes', 'A car travels 150 km in 1 hour 30 minutes. Find its average speed in km/h and in m/s.', ['Change 1 h 30 min to hours: 1.5 hours.', 'Speed = distance ÷ time = 150 ÷ 1.5 = 100 km/h.', 'To change to m/s: 100 km/h = 100 000 m in 3 600 s.', '100 000 ÷ 3 600 ≈ 27.8 m/s.'], ['1 h 30 min = 1.5 h', '150 ÷ 1.5 = 100', '100 000 ÷ 3 600', '27.8 m/s'], '100 km/h, which is about 27.8 m/s', 'Speed limits are in miles or kilometres per hour, but physics uses metres per second.', 'how to find speeds and change between km/h and m/s.', ['Divide km/h by 3.6 to get m/s.', 'Multiply m/s by 3.6 to get km/h.'], ['Example 1: 36 km/h = 10 m/s.', 'Example 2: 5 m/s = 18 km/h.', 'Example 3: 90 km in 1.5 hours is 60 km/h.']);
S.s2comp = X('Compound shapes with missing lengths', 'An L-shaped floor is a 10 m by 6 m rectangle with a 4 m by 3 m corner removed. Find its area.', ['Area of the large rectangle = 10 × 6 = 60 m².', 'Area removed = 4 × 3 = 12 m².', 'Area of the L-shape = 60 − 12 = 48 m².', 'Check by splitting: 10 × 3 + 6 × 3 = 30 + 18 = 48 ✓.'], ['10 × 6 = 60', '4 × 3 = 12', '60 − 12', '48 m²'], '48 m²', 'Flooring and paint for odd-shaped rooms need compound areas.', 'how to find areas by adding or taking away rectangles.', ['Either add parts or subtract a missing part.', 'Check with the other method.'], ['Example 1: two rectangles 3 by 4 and 2 by 5 give 22.', 'Example 2: a 5 by 5 square with a 2 by 2 hole has area 21.', 'Example 3: write each area before adding.']);
S.s2vol = X('Volume problems with changing units', 'A tank is 2 m long, 50 cm wide and 40 cm high. How many litres does it hold?', ['Change everything to cm: 200 cm by 50 cm by 40 cm.', 'Volume = 200 × 50 × 40 = 400 000 cm³.', '1 litre = 1 000 cm³.', '400 000 ÷ 1 000 = 400 litres.'], ['200 × 50 × 40', '400 000 cm³', '1 l = 1 000 cm³', '400 litres'], '400 litres', 'Fish tanks, water tanks and swimming pools are measured in litres.', 'how to change a volume in cm³ to litres.', ['Use the same unit for all three lengths.', '1 m³ = 1 000 litres.'], ['Example 1: 1 000 cm³ is 1 litre.', 'Example 2: a 1 m cube holds 1 000 litres.', 'Example 3: 2 l is 2 000 cm³.']);
S.s2fib = X('Sequences that are not linear', 'Find the next two terms of 1, 4, 9, 16 and of 1, 1, 2, 3, 5.', ['1, 4, 9, 16 are square numbers: 1², 2², 3², 4². The next are 5² = 25 and 6² = 36.', 'In 1, 1, 2, 3, 5 each term is the sum of the two before it.', '3 + 5 = 8, and 5 + 8 = 13.', 'The next terms are 25, 36 and 8, 13.'], ['squares: 1², 2², 3², 4²', '25, 36', 'add the last two', '8, 13'], '25, 36 and 8, 13', 'Patterns in nature, such as petals and spirals, follow sequences like these.', 'how to continue sequences that are not linear.', ['Check the differences. If they are not constant, the sequence is not linear.', 'Look for squares, cubes and sums of earlier terms.'], ['Example 1: 1, 8, 27, 64 are cube numbers.', 'Example 2: 2, 4, 8, 16 doubles each time.', 'Example 3: triangle numbers 1, 3, 6, 10 add 2, 3, 4.']);
S.s2par = X('Parallel lines with algebra', 'Two parallel lines are crossed by a third line. Co-interior angles are (3x + 10)° and (2x + 20)°. Find x and the angles.', ['Co-interior angles between parallel lines add up to 180°.', '3x + 10 + 2x + 20 = 180, so 5x + 30 = 180.', '5x = 150, so x = 30.', 'The angles are 3 × 30 + 10 = 100° and 2 × 30 + 20 = 80°.'], ['sum = 180°', '5x + 30 = 180', 'x = 30', '100° and 80°'], 'x = 30, angles 100° and 80°', 'Engineers use angle facts to design frames and bridges.', 'how to solve angle problems on parallel lines using an equation.', ['Corresponding and alternate angles are equal.', 'Co-interior angles add to 180°.'], ['Example 1: alternate angles are equal, so 4x = 2x + 30 gives x = 15.', 'Example 2: corresponding angles are equal.', 'Example 3: check by adding co-interior angles.']);
S.s2enl = X('Enlarging a shape about the origin', 'Enlarge the triangle with vertices (1, 1), (3, 1) and (1, 2) by scale factor 2 about the origin.', ['Multiply each coordinate by 2.', '(1, 1) → (2, 2), (3, 1) → (6, 2) and (1, 2) → (2, 4).', 'Every side of the image is twice as long.', 'The area goes from 1 square unit to 4, which is 2² times bigger.'], ['(1, 1) → (2, 2)', '(3, 1) → (6, 2)', '(1, 2) → (2, 4)', 'area × 4'], '(2, 2), (6, 2) and (2, 4)', 'Photocopiers and map makers enlarge shapes.', 'how to enlarge a shape from the origin using a scale factor.', ['Multiply both coordinates by the scale factor.', 'The area is multiplied by the scale factor squared.'], ['Example 1: (2, 3) enlarged by 3 is (6, 9).', 'Example 2: scale factor ½ halves each coordinate.', 'Example 3: the centre of enlargement stays fixed.']);
S.s2pie = X('Drawing pie charts with angles', '120 pupils choose a sport: football 45, netball 30, swimming 25 and other 20. Find the angle for football and draw the plan for the chart.', ['The whole circle is 360° for 120 pupils.', '1 pupil is 360 ÷ 120 = 3°.', 'Football: 45 × 3 = 135°. Netball: 30 × 3 = 90°. Swimming: 25 × 3 = 75°. Other: 20 × 3 = 60°.', 'Check the angles add up to 360°: 135 + 90 + 75 + 60 = 360 ✓.'], ['360 ÷ 120 = 3°', '45 × 3 = 135°', '90°, 75°, 60°', 'total 360°'], 'football 135°', 'Pie charts show how a whole is shared out.', 'how to work out the angles for a pie chart.', ['Find the angle for one item first.', 'Check the total is 360°.'], ['Example 1: 20 of 80 is 90°.', 'Example 2: 10 of 36 is 100°.', 'Example 3: use a protractor to draw each sector.']);

/* ---------- S1: extra slides for topics that were thin ---------- */
S.s1order = X('Ordering fractions, decimals and percentages', 'Put these in order from smallest to largest: 0.65, 2/3, 62%, 3/5.', ['Change every number to a decimal.', '0.65; 2 ÷ 3 = 0.667; 62% = 0.62; 3 ÷ 5 = 0.6.', 'Order the decimals: 0.6, 0.62, 0.65, 0.667.', 'So the order is 3/5, 62%, 0.65, 2/3.'], ['0.65, 0.667, 0.62, 0.6', 'compare the decimals', '0.6 < 0.62 < 0.65 < 0.667', '3/5, 62%, 0.65, 2/3'], '3/5, 62%, 0.65, 2/3', 'Shops, sports tables and surveys mix fractions, decimals and percentages.', 'how to compare fractions, decimals and percentages.', ['Change everything to decimals or to percentages.', 'Line up the decimal places before comparing.'], ['Example 1: 1/4 = 0.25 = 25%.', 'Example 2: 3/8 = 0.375 = 37.5%.', 'Example 3: 0.7 is bigger than 65%.']);
S.s1recipe = X('Scaling a recipe with a ratio', 'A recipe for 4 people uses 300 g of flour and 2 eggs. How much is needed for 10 people?', ['Find the amount for one person: 300 ÷ 4 = 75 g of flour and 2 ÷ 4 = 0.5 egg.', 'For 10 people: 75 × 10 = 750 g of flour.', 'Eggs: 0.5 × 10 = 5.', '10 people need 750 g of flour and 5 eggs.'], ['300 ÷ 4 = 75', '75 × 10 = 750', '0.5 × 10 = 5', '750 g and 5 eggs'], '750 g flour and 5 eggs', 'Cooks scale recipes up and down all the time.', 'how to scale a recipe using one portion.', ['Divide to find one, then multiply.', 'Check the ratio still holds.'], ['Example 1: 2 : 1 flour to sugar with 300 g flour needs 150 g sugar.', 'Example 2: double a recipe by multiplying everything by 2.', 'Example 3: halve it by dividing everything by 2.']);
S.s1sale = X('Discounts and sale prices', 'A jacket costs £60 and is reduced by 25%. Find the sale price.', ['10% of £60 = £6, so 20% = £12 and 5% = £3.', '25% = 12 + 3 = £15.', 'Sale price = 60 − 15 = £45.', 'Check: 75% of 60 = 45 ✓.'], ['10% = 6', '25% = 12 + 3 = 15', '60 − 15', '£45'], '£45', 'Sales and special offers use percentage discounts.', 'how to find a discount and the sale price.', ['Find the discount, then subtract it.', 'Or find the percentage you pay, for example 75%.'], ['Example 1: 10% off £30 is £27.', 'Example 2: 50% off £44 is £22.', 'Example 3: 20% off £80 is £64.']);
S.s1dst = X('Using speed, distance and time', 'A train travels at 80 km/h for 2.5 hours. How far does it go?', ['Distance = speed × time.', '80 × 2.5 = 200.', 'The train goes 200 km.', 'Check: 200 ÷ 80 = 2.5 hours ✓.'], ['distance = speed × time', '80 × 2.5', '200 km', '200 ÷ 80 = 2.5'], '200 km', 'Journey planners use speed, distance and time.', 'how to find a distance from a speed and a time.', ['Make sure the units match: km/h with hours.', 'Use the triangle D, S, T to remember the formulae.'], ['Example 1: 60 km/h for 3 hours is 180 km.', 'Example 2: time = distance ÷ speed.', 'Example 3: speed = distance ÷ time.']);
S.s1fence = X('Perimeter and area problems with costs', 'A rectangular garden is 12 m by 7 m. Fencing costs £8 a metre and grass seed costs £1.50 for each square metre. Find both costs.', ['Perimeter = 2 × (12 + 7) = 38 m.', 'Fencing = 38 × 8 = £304.', 'Area = 12 × 7 = 84 m².', 'Seed = 84 × 1.50 = £126.'], ['2 × (12 + 7) = 38', '38 × 8 = 304', '12 × 7 = 84', '84 × 1.5 = 126'], '£304 and £126', 'Gardeners and builders work out costs from perimeters and areas.', 'how to use perimeter and area to find a total cost.', ['Perimeter is a length. Area is a surface.', 'Write the units each time.'], ['Example 1: a 5 m by 4 m room has perimeter 18 m.', 'Example 2: carpet is bought by the square metre.', 'Example 3: fencing is bought by the metre.']);
S.s1dp = X('Rounding answers in context', 'Four friends share a £47.50 bill equally. The calculator shows 11.875. How much does each person pay?', ['Money is rounded to 2 decimal places, because the smallest coin is 1p.', 'The third decimal place is 5, so round up: 11.875 becomes 11.88.', 'Each friend pays £11.88, which makes 4 × 11.88 = £47.52 in total.', 'That is 2p too much, so one friend might pay £11.87 instead.'], ['2 decimal places', '11.875 → 11.88', '4 × 11.88 = 47.52', '£11.88'], '£11.88 each (or £11.87 for one person)', 'Prices, measurements and sports times are always rounded in a sensible way.', 'how to round to a given number of decimal places and decide what makes sense.', ['Look at the digit after the one you are rounding to.', 'Think about what the answer is for.'], ['Example 1: 3.14159 to 2 decimal places is 3.14.', 'Example 2: 7.996 to 1 decimal place is 8.0.', 'Example 3: 0.045 to 2 decimal places is 0.05.']);
S.s1pow10 = X('Powers of 10 with decimals', 'Work out 3.6 × 100, 45 ÷ 1 000 and 0.07 × 10 000.', ['Multiplying by 100 moves every digit 2 places to the left: 3.6 × 100 = 360.', 'Dividing by 1 000 moves every digit 3 places to the right: 45 ÷ 1 000 = 0.045.', '0.07 × 10 000 moves 4 places left: 700.', 'Notice 10³ = 1 000, so dividing by 1 000 is the same as multiplying by 10⁻³.'], ['3.6 × 100 = 360', '45 ÷ 1 000 = 0.045', '0.07 × 10 000 = 700', 'links to powers of 10'], '360, 0.045 and 700', 'Metric units and standard form are built on powers of 10.', 'how to multiply and divide decimals by powers of 10.', ['The decimal point does not move. The digits do.', 'Fill empty places with zeros.'], ['Example 1: 0.5 × 1 000 = 500.', 'Example 2: 7 ÷ 100 = 0.07.', 'Example 3: 2.5 m = 250 cm.']);
S.s1long = X('Long division and remainders in context', 'A baker packs 1 000 buns into boxes of 24. How many full boxes are there, and how many buns are left over?', ['Divide 1 000 by 24 by chunking: 24 × 40 = 960, so 40 boxes use 960 buns.', '1 000 − 960 = 40 buns remain. One more box uses 24, so 40 − 24 = 16 remain.', 'That is 41 full boxes and 16 buns left over.', 'So 1 000 ÷ 24 = 41 remainder 16.'], ['24 × 40 = 960', '1 000 − 960 = 40', '40 − 24 = 16', '41 remainder 16'], '41 full boxes and 16 buns left over', 'Packing, sharing and timetables all have remainders.', 'how to divide a large number and decide what to do with the remainder.', ['Subtract chunks of the divisor.', 'Decide whether to round the answer up or down in a real problem.'], ['Example 1: 500 ÷ 12 = 41 remainder 8.', 'Example 2: 3 584 ÷ 16 = 224.', 'Example 3: if everyone needs a seat, round the number of buses up.']);
S.s1decmul = X('Multiplying decimals', 'Work out 3.2 × 0.4.', ['Ignore the decimal points: 32 × 4 = 128.', 'Count the decimal places: 3.2 has 1 and 0.4 has 1, so there are 2 in total.', 'Put 2 decimal places back in the answer: 1.28.', 'Check by estimating: 3 × 0.4 = 1.2, which is close to 1.28 ✓.'], ['32 × 4 = 128', '1 + 1 = 2 decimal places', '1.28', 'estimate 1.2'], '1.28', 'Prices, areas and measurements often involve decimals.', 'how to multiply two decimals.', ['Count the total decimal places in the question.', 'Estimate first to check where the decimal point goes.'], ['Example 1: 0.5 × 0.6 = 0.3.', 'Example 2: 1.5 × 2 = 3.', 'Example 3: 0.12 × 10 = 1.2.']);
S.s1pf = X('Prime factors, HCF and LCM', 'Write 72 and 60 as products of prime factors, then find their HCF and LCM.', ['Use a factor tree: 72 = 2 × 2 × 2 × 3 × 3 = 2³ × 3².', '60 = 2 × 2 × 3 × 5 = 2² × 3 × 5.', 'HCF: take the primes in both, with the smaller powers: 2² × 3 = 12.', 'LCM: take every prime, with the larger powers: 2³ × 3² × 5 = 360.'], ['72 = 2³ × 3²', '60 = 2² × 3 × 5', 'HCF = 2² × 3 = 12', 'LCM = 360'], 'HCF = 12 and LCM = 360', 'Prime factors help to simplify fractions and to find when two events happen together.', 'how to use prime factors to find the HCF and LCM.', ['Keep splitting until every branch ends in a prime.', 'HCF uses the smaller powers, LCM the larger.'], ['Example 1: 12 = 2² × 3.', 'Example 2: HCF of 8 and 12 is 4.', 'Example 3: LCM of 4 and 6 is 12.']);
S.s1negctx = X('Negative numbers in real situations', 'At 6 a.m. the temperature is −5 °C. By noon it has risen to 8 °C. By how many degrees did it rise?', ['Count up from −5 to 0: that is 5 degrees.', 'Then from 0 to 8: that is 8 degrees.', 'The total rise is 5 + 8 = 13 degrees.', 'Or subtract: 8 − (−5) = 8 + 5 = 13.'], ['−5 to 0 is 5', '0 to 8 is 8', '5 + 8 = 13', '8 − (−5) = 13'], '13 °C', 'Temperature, bank balances and heights above and below sea level use negative numbers.', 'how to find differences that cross zero.', ['Subtracting a negative is the same as adding.', 'Draw a number line to check.'], ['Example 1: a balance of −£20 plus a deposit of £50 is £30.', 'Example 2: the difference between −3 and 4 is 7.', 'Example 3: from 5 m above to 3 m below sea level is a drop of 8 m.']);
S.s2fracprob = X('Fraction problems with what is left', 'Ali spends 1/3 of his money on a game and 2/5 of the rest on lunch. He has £12 left. How much did he start with?', ['After the game, 2/3 is left.', 'Lunch costs 2/5 of 2/3 = 4/15.', 'Left = 2/3 − 4/15 = 10/15 − 4/15 = 6/15 = 2/5.', '2/5 of the money is £12, so 1/5 is £6 and the start was 5 × 6 = £30.'], ['2/3 left', '2/5 × 2/3 = 4/15', '2/5 left = £12', '£30'], '£30', 'Budgets and shared costs involve fractions of what remains.', 'how to solve multi-step fraction problems by working out what is left.', ['Draw a bar and shade the parts.', 'Work out the fraction left at each step.'], ['Example 1: 1/2 of 1/2 is 1/4.', 'Example 2: if 3/5 is £45 then 1/5 is £15.', 'Example 3: check by adding the spent parts and what is left.']);
S.s1unit = X('Unit rates and simple proportion', '5 pens cost £3.50. How much do 8 pens cost?', ['Find the cost of 1 pen: 3.50 ÷ 5 = £0.70.', '8 pens cost 8 × 0.70 = £5.60.', 'Check: 8 is 1.6 times 5, and 3.50 × 1.6 = 5.60 ✓.', 'Always find the cost of one first.'], ['3.50 ÷ 5 = 0.70', '8 × 0.70 = 5.60', 'check × 1.6', '£5.60'], '£5.60', 'Shopping, cooking and fuel use unit rates.', 'how to use the cost of one item to find the cost of several.', ['Divide to find one, then multiply.', 'Check that the answer is sensible.'], ['Example 1: 4 apples cost £1.20, so 10 cost £3.', 'Example 2: 60 miles in 2 hours is 30 miles an hour.', 'Example 3: a unit rate compares fairly.']);
S.s1budget = X('Budgets and bills', 'Sam earns £320 a week. Rent is 40% of this, food costs £75 and travel costs £28. How much is left?', ['Rent = 40% of 320 = 0.4 × 320 = £128.', 'Total spending = 128 + 75 + 28 = £231.', 'Money left = 320 − 231 = £89.', 'As a percentage of pay: 89 ÷ 320 ≈ 27.8%.'], ['0.4 × 320 = 128', '128 + 75 + 28 = 231', '320 − 231 = 89', '≈ 27.8%'], '£89 left', 'A budget shows where money goes and what can be saved.', 'how to plan a budget using percentages and totals.', ['Add all the spending before subtracting.', 'Check the parts add up to the whole.'], ['Example 1: 10% saved from £250 is £25.', 'Example 2: a £30 bill on a £200 budget uses 15%.', 'Example 3: weekly costs × 52 give the yearly cost.']);
S.s1tri = X('Angles in a triangle with algebra', 'The angles of a triangle are 2x, 3x and 4x degrees. Find x and the three angles.', ['Angles in a triangle add up to 180°.', '2x + 3x + 4x = 9x = 180.', 'x = 180 ÷ 9 = 20.', 'The angles are 40°, 60° and 80°.'], ['2x + 3x + 4x = 180', '9x = 180', 'x = 20', '40°, 60°, 80°'], 'x = 20; the angles are 40°, 60° and 80°', 'Builders use angle rules to design roofs and frames.', 'how to form an equation from angles and solve it.', ['Write the sum of the angles and set it equal to 180°.', 'Check that the angles add to 180°.'], ['Example 1: angles x, x and 80 give x = 50.', 'Example 2: a right angle and two equal angles are 45° each.', 'Example 3: an isosceles triangle has two equal angles.']);
S.s1mid = X('Midpoints on a coordinate grid', 'Find the midpoint of A(2, 3) and B(8, 7).', ['The midpoint is halfway between the two points.', 'Add the x values and halve: (2 + 8) ÷ 2 = 5.', 'Add the y values and halve: (3 + 7) ÷ 2 = 5.', 'The midpoint is (5, 5).'], ['halfway', '(2 + 8) ÷ 2 = 5', '(3 + 7) ÷ 2 = 5', '(5, 5)'], '(5, 5)', 'Maps and games use midpoints to find the centre of a line.', 'how to find the midpoint of two points.', ['Find the mean of the x values and the mean of the y values.', 'Plot the points to check.'], ['Example 1: the midpoint of (0, 0) and (6, 4) is (3, 2).', 'Example 2: the midpoint of (−2, 1) and (4, 5) is (1, 3).', 'Example 3: a point and its midpoint are as far from each end as each other.']);
S.s2meanfreq = X('Mean from a frequency table', 'Shoe sizes: size 3 (4 pupils), size 4 (6), size 5 (8) and size 6 (2). Find the mean size.', ['Multiply each size by its frequency: 3 × 4 = 12, 4 × 6 = 24, 5 × 8 = 40, 6 × 2 = 12.', 'Add these: 12 + 24 + 40 + 12 = 88.', 'The total frequency is 4 + 6 + 8 + 2 = 20.', 'Mean = 88 ÷ 20 = 4.4.'], ['size × frequency', '12 + 24 + 40 + 12 = 88', '4 + 6 + 8 + 2 = 20', '88 ÷ 20 = 4.4'], '4.4', 'Shops use the mean size to decide how many shoes to stock.', 'how to find a mean from a frequency table.', ['Add a column for size × frequency.', 'Divide the total by the number of items, not the number of rows.'], ['Example 1: marks 1 (2), 2 (3), 3 (5) give a mean of 2.3.', 'Example 2: the mode is the size with the highest frequency.', 'Example 3: the median is the middle value.']);
S.s2cmp = X('Comparing data using averages and range', 'Team A scores have mean 24 and range 10. Team B scores have mean 22 and range 4. Compare the teams.', ['A higher mean means a higher typical score. Team A has the higher mean (24 > 22).', 'A smaller range means the scores are more consistent. Team B has the smaller range (4 < 10).', 'So Team A usually scores more, but Team B is more consistent.', 'Always make one comment about the average and one about the spread.'], ['mean A > mean B', 'range B < range A', 'A scores more', 'B is more consistent'], 'Team A scores more on average; Team B is more consistent', 'Coaches and teachers compare groups with an average and a spread.', 'how to compare two sets of data.', ['Use the mean, median or mode for the typical value.', 'Use the range for the spread.'], ['Example 1: a bigger range means more spread.', 'Example 2: a smaller mean means lower scores.', 'Example 3: write your comment in the context of the question.']);
S.s2share = X('Sharing in a ratio with three parts', 'Money is shared between A, B and C in the ratio 2 : 3 : 5. B gets £45. How much is shared altogether and how much does C get?', ['3 parts are £45, so 1 part is £15.', 'There are 2 + 3 + 5 = 10 parts, so the total is 10 × 15 = £150.', 'C gets 5 parts: 5 × 15 = £75.', 'Check: A gets £30, B £45, C £75, and 30 + 45 + 75 = 150 ✓.'], ['3 parts = 45', '10 parts = 150', 'C = 5 × 15 = 75', 'total 150 ✓'], 'a total of £150 and C gets £75', 'Profits and prizes are often shared in a ratio.', 'how to share an amount in a ratio when you know one share.', ['Find the value of one part first.', 'Check that the shares add up to the total.'], ['Example 1: shares 1 : 2 : 3 of £60 are £10, £20, £30.', 'Example 2: if C gets 5 parts and B gets 3, C gets £30 more than B when a part is £15.', 'Example 3: the total number of parts is the sum of the ratio.']);
S.s3frac = X('Equations with fractions', 'Solve (x + 3) ÷ 4 = 5 and 2x ÷ 3 − 1 = 5.', ['For the first equation, multiply both sides by 4: x + 3 = 20, so x = 17.', 'For the second, add 1 to both sides: 2x ÷ 3 = 6.', 'Multiply both sides by 3: 2x = 18.', 'Divide by 2: x = 9.'], ['× 4: x + 3 = 20', 'x = 17', '2x ÷ 3 = 6 → 2x = 18', 'x = 9'], 'x = 17 and x = 9', 'Rates and proportions in formulae often include fractions.', 'how to solve equations that contain fractions.', ['Clear the fraction by multiplying both sides.', 'Check your answer by substituting back.'], ['Example 1: x ÷ 5 = 3 gives x = 15.', 'Example 2: 3x ÷ 4 = 6 gives x = 8.', 'Example 3: (x − 1) ÷ 2 = 4 gives x = 9.']);
S.s1bear = X('Measuring a bearing', 'Find the three-figure bearing of B from A when B is due East of A, and then the bearing of A from B.', ['A bearing is an angle measured clockwise from North, written with three figures.', 'East is a quarter turn clockwise from North: 090°.', 'To find the way back, turn through 180°: 090° + 180° = 270°.', 'The bearing of A from B is 270°.'], ['clockwise from North', 'East = 090°', '090° + 180°', '270°'], '090° and 270°', 'Walkers, pilots and sailors use bearings.', 'how to read a simple bearing.', ['Always start from North and turn clockwise.', 'Always write three figures, for example 045°.'], ['Example 1: South is 180°.', 'Example 2: North-East is 045°.', 'Example 3: West is 270°.']);
})();
